n = int(input())
managers = [0] * (n + 1)
for i in range(1, n + 1):
    managers[i] = int(input())

# Create a list to store the group number for each employee
group_number = [0] * (n + 1)

# Function to find the root of the superior chain
def find_root(employee):
    if group_number[employee] == 0:
        return employee
    root = find_root(managers[employee])
    group_number[employee] = root
    return root

# Assign group numbers based on the superior chain
for i in range(1, n + 1):
    if managers[i] != -1:
        group_number[i] = find_root(managers[i])

# Count the number of unique groups
unique_groups = set(group_number[1:])

# The minimum number of groups is the number of unique groups
print(len(unique_groups))
